+function generatedSections(where: string, text: string): string[] {
+  const problems: string[] = [];
+  for (const heading of REQUIRED_SECTIONS) {
+    if (!new RegExp(`^${heading}\\b`, "m").test(text)) problems.push(`${where}: missing section "${heading}"`);
+  }
+  if (!text.includes(PHI_HEADING)) problems.push(`${where}: missing "${PHI_HEADING}" block`);
+  if (!text.includes(CARD_HEADING)) problems.push(`${where}: missing "${CARD_HEADING}"`);
+  return problems;
+}
