+  file(id: string): string;
+  /** Problems for one role file's structure and generated sections. */
+  check(where: string, source: string, id: string): string[];
+}
+
+const mdIds = (dir: string): string[] => readdirSync(dir).filter((f) => /^[a-z0-9][a-z0-9-]*\.md$/.test(f)).map((f) => f.slice(0, -3));
+
+function mdAgent(requireName: boolean, extra?: (fm: Record<string, string | string[]>) => string[]) {
+  return (where: string, source: string, id: string): string[] => {
+    try {
+      const { frontmatter: fm, body } = parseAgent(source);
+      const problems: string[] = [];
+      if (typeof fm["description"] !== "string" || fm["description"] === "") problems.push(`${where}: missing description`);
+      if (requireName && fm["name"] !== id) problems.push(`${where}: name "${String(fm["name"])}" does not match ${id}`);
+      if (extra) problems.push(...extra(fm).map((p) => `${where}: ${p}`));
+      return [...problems, ...generatedSections(where, body)];
+    } catch (err) {
+      return [`${where}: ${err instanceof Error ? err.message : String(err)}`];
+    }
+  };
+}
+
+export const HARNESSES: Record<string, HarnessSpec> = {
+  codex: {
+    dir: ".codex/agents",
+    list: (dir) => readdirSync(dir).filter((f) => /^[a-z0-9][a-z0-9-]*\.toml$/.test(f)).map((f) => f.slice(0, -5)),
+    file: (id) => `${id}.toml`,
+    check: (where, source, id) => {
+      try {
+        const t = parseFlatToml(source);
+        const problems: string[] = [];
+        for (const k of ["name", "description", "developer_instructions"]) if (!t[k]) problems.push(`${where}: missing "${k}"`);
+        for (const k of Object.keys(t)) if (!CODEX_KEYS.has(k)) problems.push(`${where}: key "${k}" is not allowed in a generated Codex agent`);
+        if (t["sandbox_mode"] !== undefined && !CODEX_SANDBOX.has(t["sandbox_mode"])) problems.push(`${where}: sandbox_mode "${t["sandbox_mode"]}" is not allowed`);
+        if (GATE_ROLES.has(id) && t["sandbox_mode"] !== "read-only") problems.push(`${where}: gate role must have sandbox_mode = "read-only"`);
+        if (t["name"] !== undefined && t["name"] !== id) problems.push(`${where}: name "${t["name"]}" does not match ${id}`);
