+description = "Storage, search, indexing, schema and tenancy specialist for the WSO2 FHIR Server. Use for any change to internal/store (search.go, bundle.go, integrity.go), internal/index, internal/db (schema.sql), internal/searchparam, row-level security, search parameter behaviour, SQL, query plans, or schema migrations. Enforces fail-closed search and tenant isolation."
+config_file = "agents/fhir-storage-search-engineer.toml"
+
+[agents.fhir-test-engineer]
+description = "Test engineering for the WSO2 FHIR Server. Use when designing or writing unit tests, testcontainers-based integration tests, race-detector runs, conformance tests, golden snapshots, or benchmarks; when a change needs its test plan; when CI tests fail; or to confirm the StoreAPI mock stays in sync with the store."
+config_file = "agents/fhir-test-engineer.toml"
+
+[agents.fhir-code-reviewer]
+description = "Read-only diff review for the WSO2 FHIR Server against its conventions, blocking constraints and domain rules. Use after any implementation task or change is done and before archive, or when asked to review a diff, branch or PR. Returns severity-ranked findings (CRITICAL/WARNING/SUGGESTION) and a PASS/BLOCK verdict; never edits files."
+config_file = "agents/fhir-code-reviewer.toml"
+
