+description = "Read-only security and healthcare-compliance review for the WSO2 FHIR Server. Use for any change touching authentication, tenancy or row-level security, SQL construction, error messages, logging or observability, test fixtures, IG/terminology network calls, Helm secrets, or the committed .prometheus/ agent logs. Checks PHI/HIPAA exposure, tenant leakage, injection and secret handling; returns PASS/BLOCK with severity-ranked findings."
+config_file = "agents/fhir-security-compliance-reviewer.toml"
+
+[agents.fhir-conformance-validator]
+description = "Final archive gate for WSO2 FHIR Server changes. Use after implementation and code/security review, before /opsx:archive or kbd-apply archive, and for /kbd-goal-check. Runs openspec validate, each task's verification, build/vet/test and the CI-parity race-integration suite when store/handler changed, then reports PASS only if everything succeeds. Read-only."
+config_file = "agents/fhir-conformance-validator.toml"
+
