+config_file = "agents/fhir-infra-release-engineer.toml"
+
+[agents.hipaa-privacy-officer]
+description = "HIPAA privacy and security policy owner for the WSO2 FHIR Server used as an intermediate EHR for AI. Use when a change or integration adds a PHI data flow, a new partner feed or data category, a new model endpoint or PHI destination, or a logging/retention decision; for minimum-necessary assessments, BAA prerequisites, PHI-lane recommendations (ATH-D-001), access and audit control reviews, and breach-assessment steps. Reviews policy; never processes PHI itself."
+config_file = "agents/hipaa-privacy-officer.toml"
+
+[agents.fhir-integration-specialist]
+description = "FHIR protocol and interoperability specialist for pulling patient data from partner EHRs (Epic, Oracle Health/Cerner, athenahealth, any FHIR R4 server) into this intermediate EHR. Use for FHIR R4 REST and Bulk Data $export design, SMART on FHIR and backend-services authorization, US Core conformance and mapping, patient matching, Provenance, and debugging partner FHIR responses. Sandbox-first; real endpoints only on a Tribe PHI lane."
+config_file = "agents/fhir-integration-specialist.toml"
+
+[agents.ehr-integration-manager]
+description = "Business owner of partner EHR integrations. Use when onboarding a new partner EHR, tracking integration status, running a go-live checklist, defining or reviewing integration SLAs, coordinating partner contacts and maintenance windows, or managing an integration incident's communication. Works on process and status documents; no PHI and no code."
+config_file = "agents/ehr-integration-manager.toml"
+
+[agents.data-sync-coordinator]
+description = "Coordinates recurring data synchronization between partner EHRs and this FHIR server. Use when setting or changing a sync schedule, investigating stale or missing data, reconciling partner vs ingested counts after a run, handling a sync failure or partner outage, or writing a sync incident report. Real partner runs only on a Tribe PHI lane."
+config_file = "agents/data-sync-coordinator.toml"
+
+[agents.billing-prior-auth-specialist]
+description = "Billing, coding and prior-authorization specialist. Use to determine what must be documented in the medical record to bill a procedure for a specific payer, whether prior authorization is required and how to submit it (X12 278, Da Vinci PAS, CMS-0057-F), CPT/HCPCS/ICD-10 linkage and medical necessity, and how to work denials and appeals (CARC/RARC). Cites a source for every payer rule; drafts with real patient details only on a Tribe PHI lane."
+config_file = "agents/billing-prior-auth-specialist.toml"
